// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DE GATEWAYS (ASAAS, STRIPE, PAGAR.ME, PAGBANK, EFI)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

let gateway = 'Asaas';
if (body.event && body.payment) gateway = 'Asaas';
else if (body.type && body.data?.object) gateway = 'Stripe';
else if (body.charges || body.current_status) gateway = 'Pagar.me';
else gateway = 'Gateway Pagamento';

let rawPhone = '';
let clienteNome = 'Cliente';
let clienteEmail = '';
let valorTotal = 0;
let statusOperacional = 'Pendente';
let linkPagamento = '';
let idTransacao = Date.now().toString();

if (gateway === 'Asaas') {
  const pay = body.payment || {};
  idTransacao = pay.id || idTransacao;
  valorTotal = parseFloat(pay.value || pay.netValue || 0);
  linkPagamento = pay.bankSlipUrl || pay.invoiceUrl || '';
  const evt = (body.event || '').toUpperCase();
  if (['PAYMENT_RECEIVED', 'PAYMENT_CONFIRMED'].includes(evt)) statusOperacional = 'Pago';
  else if (['PAYMENT_OVERDUE', 'PAYMENT_DELETED'].includes(evt)) statusOperacional = 'Cancelado';
  else if (['PAYMENT_CREATED'].includes(evt)) statusOperacional = pay.billingType === 'BOLETO' ? 'Pendente_Boleto' : 'Pendente_PIX';
} else if (gateway === 'Stripe') {
  const obj = body.data?.object || {};
  idTransacao = obj.id || idTransacao;
  valorTotal = parseFloat(obj.amount || obj.amount_total || 0) / 100.0;
  clienteEmail = obj.customer_details?.email || obj.billing_details?.email || '';
  clienteNome = obj.customer_details?.name || obj.billing_details?.name || 'Cliente Stripe';
  rawPhone = (obj.customer_details?.phone || '').replace(/\D/g, '');
  const evt = (body.type || '').toLowerCase();
  if (evt.includes('checkout.session.completed') || evt.includes('charge.succeeded')) statusOperacional = 'Pago';
} else if (gateway === 'Pagar.me') {
  idTransacao = body.id || idTransacao;
  valorTotal = parseFloat(body.amount || 0) / 100.0;
  const cust = body.customer || {};
  clienteNome = cust.name || 'Cliente Pagar.me';
  clienteEmail = cust.email || '';
  rawPhone = (cust.phones?.mobile_phone ? `${cust.phones.mobile_phone.ddd_code}${cust.phones.mobile_phone.number}` : '').replace(/\D/g, '');
  const st = (body.status || '').toLowerCase();
  if (['paid', 'captured'].includes(st)) statusOperacional = 'Pago';
}

if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const numeroPedido = parseInt(idTransacao.replace(/\D/g, '').slice(-8) || Date.now().toString().slice(-8), 10);
const dedupHash = crypto.createHash('sha256').update(`${gateway}_${idTransacao}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    gateway: gateway,
    id_transacao: idTransacao,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    valor_total: valorTotal,
    link_pagamento: linkPagamento,
    status_operacional: statusOperacional
  }
}];
